package com.google.javascript.rhino;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TokenStream_isJSIdentifier_TriageGen0Test {

    @Test
    public void testEmptyString() {
        assertFalse(TokenStream.isJSIdentifier(""));
    }

    @Test
    public void testInvalidStartCharacter() {
        // Starts with a digit, which is not a valid identifier start
        assertFalse(TokenStream.isJSIdentifier("1abc"));
        // Starts with a symbol
        assertFalse(TokenStream.isJSIdentifier("$#abc")); // Note: depends on Character.isJavaIdentifierStart
        // Actually, based on Character.isJavaIdentifierStart:
        assertFalse(TokenStream.isJSIdentifier("!abc"));
    }

    @Test
    public void testValidSingleCharacter() {
        assertTrue(TokenStream.isJSIdentifier("a"));
        assertTrue(TokenStream.isJSIdentifier("_"));
    }

    @Test
    public void testValidMultiCharacter() {
        assertTrue(TokenStream.isJSIdentifier("abc"));
        assertTrue(TokenStream.isJSIdentifier("var123"));
        assertTrue(TokenStream.isJSIdentifier("_underscore"));
        assertTrue(TokenStream.isJSIdentifier("a_b_c"));
    }

    @Test
    public void testInvalidPartCharacter() {
        // Valid start, but contains an invalid part (a space)
        assertFalse(TokenStream.isJSIdentifier("abc def"));
        // Valid start, but contains an invalid part (a hyphen)
        assertFalse(TokenStream.isJSIdentifier("abc-def"));
        // Valid start, but contains an invalid part (a dot)
        assertFalse(TokenStream.isJSIdentifier("abc.def"));
    }

    @Test
    public void testUnicodeIdentifiers() {
        // Testing valid Unicode identifier start/parts if supported by Character class
        assertTrue(TokenStream.isJSIdentifier("π"));
        assertFalse(TokenStream.isJSIdentifier("π!"));
    }
}
